    v_18 = params.get("frobnorm_thresh")
    if v_18 is not None:
        cargs.append("--frobnorm-thresh")
        cargs.append(str(v_18))
    v_19 = params.get("conform")
    if v_19 is not None:
        cargs.append("--conform")
        cargs.append(v_19)
    v_20 = params.get("seed")
