def mri_robust_template_outputs(params: MriRobustTemplate, execution: Execution) -> MriRobustTemplateOutputs:
    """Build the MriRobustTemplateOutputs object for this tool."""
    conform_output_v: OutputPathType | None = None
    root_v: OutputPathType = execution.output_file(".")
    template_output_v: OutputPathType = execution.output_file(params["template"])
    __v0 = params.get("conform")
    if __v0 is not None:
        conform_output_v = execution.output_file((__v0 if __v0 is not None else ""))
    return MriRobustTemplateOutputs(
        root=root_v,
        template_output=template_output_v,
        conform_output=conform_output_v,
    )

def mri_robust_template_execute(params: MriRobustTemplate, runner: Runner | None = None) -> MriRobustTemplateOutputs:
    """
    mri_robust_template

    Constructs an unbiased robust template for longitudinal volumes using an iterative method.

    Author: FreeSurfer Developers

    URL: https://github.com/freesurfer/freesurfer

    Args:
        params: The parameters.
        runner: Command runner (defaults to global runner).

    Returns:
        Tool outputs (paths to files produced by the tool).
    """
    mri_robust_template_validate(params)
    runner = runner if runner is not None else get_global_runner()
    execution = runner.start_execution(MRI_ROBUST_TEMPLATE_METADATA)
    execution.params(params)
    args = mri_robust_template_cargs(params, execution)
    out = mri_robust_template_outputs(params, execution)
    execution.run(args)
    return out

def mri_robust_template(
    mov: list[InputPathType],
    template: str,
    sat: float | None = None,
    satit: bool = False,
    lta: list[str] | None = None,
    mapmov: list[str] | None = None,
    mapmovhdr: list[str] | None = None,
    weights: list[str] | None = None,
    oneminusw: bool = False,
    average: int | None = None,
    inittp: int | None = None,
    fixtp: bool = False,
    iscale: bool = False,
    iscaleonly: bool = False,
    iscalein: list[InputPathType] | None = None,
    iscaleout: list[str] | None = None,
    transonly: bool = False,
    affine: bool = False,
    ixforms: list[InputPathType] | None = None,
    masks: list[InputPathType] | None = None,
    vox2vox: bool = False,
    leastsquares: bool = False,
    noit: bool = False,
    maxit: int | None = None,
    highit: int | None = None,
    epsit: float | None = None,
    pairmaxit: int | None = None,
    pairepsit: float | None = None,
    subsample: int | None = None,
    nomulti: bool = False,
    floattype: bool = False,
    finalnearest: bool = False,
    doubleprec: bool = False,
    cras: bool = False,
    res_thresh: float | None = None,
    frobnorm_thresh: float | None = None,
    conform: str | None = None,
    seed: int | None = None,
    allow_diff_vox_size: bool = False,
    threads: int | None = None,
    debug: bool = False,
    runner: Runner | None = None,
) -> MriRobustTemplateOutputs:
    """
    mri_robust_template

    Constructs an unbiased robust template for longitudinal volumes using an iterative method.

    Author: FreeSurfer Developers

    URL: https://github.com/freesurfer/freesurfer

    Args:
        mov: Input movable volumes to be aligned to common mean/median template (at\
            least 2 required).
        template: Output template volume (final mean/median image).
        sat: Set outlier sensitivity manually. Higher values mean less sensitivity.
        satit: Auto-detect good sensitivity (recommended for head or full brain\
            scans).
        lta: Output LTA transforms to template (one per input volume).
        mapmov: Output mapped and resampled images in template space (one per input\
            volume).
        mapmovhdr: Output header-adjusted movable images (no resampling, only\
            vox2ras adjusted).
        weights: Output weight volumes in template space (0=regular, 1=outlier).
        oneminusw: Invert outlier weight map (0=outlier), as in earlier versions.
        average: Construct template from: 0=mean, 1=median (default 1).
        inittp: Use timepoint number for spatial initialization (default: random).\
            0 constructs template from original volumes without initialization.
        fixtp: Map everything to initial timepoint (init TP is not resampled).
        iscale: Enable intensity scaling (default off).
        iscaleonly: Only perform intensity scaling (no spatial transformation).
        iscalein: Input initial intensity scale files.
        iscaleout: Output final intensity scale files (will activate --iscale).
        transonly: Find 3 parameter translation only.
        affine: Find 12 parameter affine transform.
        ixforms: Use initial LTA transforms on source ('id' for identity).
        masks: Input mask volumes applied to movable images.
        vox2vox: Output VOX2VOX LTA file (default is RAS2RAS).
        leastsquares: Use least squares instead of robust M-estimator (for testing\
            only).
        noit: Do not iterate, just create first template.
        maxit: Maximum number of template iterations (default: 6 if >2 timepoints,\
            5 otherwise).
        highit: Maximum number of iterations on highest resolution (default: -1,\
            use maxit).
        epsit: Stop template iterations when all transform updates fall below this\
            value (default: -1.0, disabled).
        pairmaxit: Maximum number of iterations for pairwise registrations\
            (default: 5).
        pairepsit: Stop pairwise registration iterations when transform updates\
            fall below this value (default: 0.01).
        subsample: Subsample if voxel dimension exceeds this value on all axes\
            (default: -1, disabled).
        nomulti: Do not use multi-resolution (process highest resolution only).
        floattype: Convert images to float internally (default: keep input type).
        finalnearest: Use nearest neighbor interpolation when creating the final\
            average.
        doubleprec: Use double precision instead of float internally (large memory\
            usage).
        cras: Center template at average CRAS instead of average barycenter.
        res_thresh: Volume resolution threshold in mm (default: 0.01).
        frobnorm_thresh: Matrix Frobenius norm threshold (default: 0.0001).
        conform: Output conformed template (256^3, 1mm isotropic voxels).
        seed: Set random seed for target selection (default: 0).
        allow_diff_vox_size: Allow input volumes with different voxel sizes.
        threads: Set number of OpenMP threads.
        debug: Show debug output.
        runner: Command runner (defaults to global runner).

    Returns:
        Tool outputs (paths to files produced by the tool).
    """
    params = mri_robust_template_params(
        mov=mov,
        template=template,
        sat=sat,
        satit=satit,
        lta=lta,
        mapmov=mapmov,
        mapmovhdr=mapmovhdr,
        weights=weights,
        oneminusw=oneminusw,
        average=average,
        inittp=inittp,
        fixtp=fixtp,
        iscale=iscale,
        iscaleonly=iscaleonly,
        iscalein=iscalein,
        iscaleout=iscaleout,
        transonly=transonly,
        affine=affine,
        ixforms=ixforms,
        masks=masks,
        vox2vox=vox2vox,
        leastsquares=leastsquares,
        noit=noit,
        maxit=maxit,
        highit=highit,
        epsit=epsit,
        pairmaxit=pairmaxit,
        pairepsit=pairepsit,
        subsample=subsample,
        nomulti=nomulti,
        floattype=floattype,
        finalnearest=finalnearest,
        doubleprec=doubleprec,
        cras=cras,
        res_thresh=res_thresh,
        frobnorm_thresh=frobnorm_thresh,
        conform=conform,
        seed=seed,
        allow_diff_vox_size=allow_diff_vox_size,
        threads=threads,
        debug=debug,
    )
    return mri_robust_template_execute(params, runner)

